import { ref } from 'vue'
import { get, set } from 'idb-keyval'
interface Mutation { id: string; noteId: string; baseVersion: number; title: string }
export const pending = ref<Mutation[]>([])
export const conflicts = ref<Mutation[]>([])
const persist = () => set('outbox', JSON.parse(JSON.stringify(pending.value)))

export async function save(noteId: string, baseVersion: number, title: string) {
  pending.value.push({ id: crypto.randomUUID(), noteId, baseVersion, title })
  await persist()
  if (navigator.onLine) await flush()
}

async function flush() {
  while (pending.value.length) {
    const m = pending.value[0]
    const res = await fetch('/api/sync', { method: 'POST', body: JSON.stringify(m),
      headers: { 'Content-Type': 'application/json' } })
    if (!res.ok && res.status !== 409) return   // server down: retry later
    const mine = pending.value.filter(p => p.noteId === m.noteId)
    if (res.status === 409) {   // park this edit and the later ones built on it
      conflicts.value.push(...mine)
      pending.value = pending.value.filter(p => !mine.includes(p))
    } else {
      const { version } = await res.json()
      pending.value.shift()
      mine.forEach(p => { p.baseVersion = version })   // later edits build on it
    }
    await persist()
  }
}

export async function startOutbox() {
  pending.value = (await get('outbox')) ?? []
  window.addEventListener('online', flush)
}

#[ORM\Entity]
class Note
{
    #[ORM\Id, ORM\Column(type: 'uuid')]
    private Uuid $id;

    #[ORM\Column(length: 200)]
    private string $title;

    #[ORM\Version, ORM\Column(type: 'integer')]
    private int $version = 1;

    public function rename(string $title): void
    {
        $this->title = $title;   // the version bumps itself on flush
    }

    public function getVersion(): int
    {
        return $this->version;
    }
}

#[Route('/api/sync', methods: ['POST'])]
public function sync(#[MapRequestPayload] SyncMutation $m): JsonResponse
{
    if ($version = $this->applied->versionOf($m->id)) {   // already applied
        return $this->json(['status' => 'duplicate', 'version' => $version]);
    }

    try {
        $note = $this->em->find(Note::class, $m->noteId, LockMode::OPTIMISTIC, $m->baseVersion);
        $note->rename($m->title);
        $this->applied->record($m->id, $m->baseVersion + 1);
        $this->em->flush();
    } catch (OptimisticLockException) {
        $server = $this->em->find(Note::class, $m->noteId);
        return $this->json(['status' => 'conflict', 'server' => $server], 409);
    }

    return $this->json(['status' => 'applied', 'version' => $note->getVersion()]);
}

#[AsMessageHandler]
final readonly class PublishOrderStatusHandler
{
    public function __construct(private HubInterface $hub) {}

    public function __invoke(OrderStatusChanged $e): void
    {
        $this->hub->publish(new Update(
            topics: 'https://shop.example/orders/'.$e->orderId,
            data: json_encode(['status' => $e->status], JSON_THROW_ON_ERROR),
            private: true,
        ));
    }
}

#[Route('/orders/{id}/live', methods: ['GET'])]
#[IsGranted('VIEW', subject: 'order')]
public function live(
    Order $order,
    Request $request,
    Authorization $authorization,
    HubInterface $hub,
): JsonResponse {
    $topic = 'https://shop.example/orders/'.$order->getId();
    $authorization->setCookie($request, [$topic]);   // permission to listen to this topic only

    return $this->json(['hub' => $hub->getPublicUrl(), 'topic' => $topic]);
}

#[AsMessageHandler]
final readonly class FanOutPostHandler
{
    private const CHUNK = 1000;
    private const FEED_MAX = 800;

    public function __invoke(FanOutPost $m): void
    {
        $ids = $this->follows->followerIdsAfter($m->authorId, $m->afterId, self::CHUNK);
        if ([] === $ids) {
            return;                                   // reached everyone
        }

        $pipe = $this->redis->multi(\Redis::PIPELINE);
        foreach ($ids as $uid) {
            $pipe->zAdd('feed:'.$uid, $m->createdAtMs, (string) $m->postId);
            $pipe->zRemRangeByRank('feed:'.$uid, 0, -(self::FEED_MAX + 1));
        }
        $pipe->exec();

        $this->bus->dispatch(new FanOutPost(
            $m->postId, $m->authorId, $m->createdAtMs, (int) end($ids),
        ));
    }
}

/** @param array{int, int}|null $cursor [createdAtMs, postId] of the last item shown */
public function page(int $userId, ?array $cursor, int $limit = 20): array
{
    [$at, $id] = $cursor ?? [null, 0];
    $key = 'feed:'.$userId;
    $opt = ['withscores' => true];

    // 1) posts in the cursor's own millisecond: take them all, keep the smaller ids
    $same = null === $at ? [] : $this->redis->zRangeByScore($key, $at, $at, $opt);
    $own = array_filter($same, fn ($score, $postId) => $postId < $id, ARRAY_FILTER_USE_BOTH);

    // 2) strictly older milliseconds, newest first
    $own += $this->redis->zRevRangeByScore(
        $key, null === $at ? '+inf' : '('.$at, '-inf', $opt + ['limit' => [0, $limit]],
    );

    $items = [];
    foreach ($own as $postId => $score) {
        $items[] = ['id' => (int) $postId, 'at' => (int) $score];
    }
    $stars = $this->follows->celebritiesFollowedBy($userId);
    foreach ($this->posts->latestBy($stars, $cursor, $limit) as $p) {
        $items[] = ['id' => $p->getId(), 'at' => $p->getCreatedAtMs()];
    }

    usort($items, fn ($a, $b) => [$b['at'], $b['id']] <=> [$a['at'], $a['id']]);

    return array_slice($items, 0, $limit);       // the last item is the next cursor
}
